/**
 * Original FORMA-authored offline text storyboards, not imported or generated
 * footage. They are reading aids, NOT professionally reviewed movement video,
 * clinical guidance, technique certification, or a media-admission record.
 * Indexed by exact exercise ID and equipment; never substitute across gear.
 */
data class AuthoredTechniqueFrame(val title: String, val instruction: String)
private data class AuthoredTechniqueScript(
 val preparation: String, val movement: String, val returnToStart: String
)
