/** No network, video, media rights, account data, or mutation of saved workouts. */
fun authoredTechniqueFrames(exercise: Exercise): List<AuthoredTechniqueFrame> {
 if (exerciseCatalog.none { it.id == exercise.id && it.equipment == exercise.equipment }) return emptyList()
 val script = authoredTechniqueScripts[exercise.id] ?: return emptyList()
 return listOf(
  AuthoredTechniqueFrame("1 · Подготовка", script.preparation),
  AuthoredTechniqueFrame("2 · Движение", script.movement),
  AuthoredTechniqueFrame("3 · Возврат", script.returnToStart),
  AuthoredTechniqueFrame("4 · Самопроверка",
   "Дышите ровно, не задерживайте дыхание. Следите за комфортной амплитудой. " +
    "Частые ошибки: " + exercise.mistakes.ifBlank { "Рывки или продолжение движения при боли." } +
    " При боли, головокружении или потере контроля прекратите упражнение.")
 )
}
